  assign n3 = ticker_every == n2;  // .every("100ms") (line 12)
  assign n5 = {{1{1'b0}}, ticker_every} + {{17{1'b0}}, n4};  // .every("100ms") (line 12)
  assign n6 = n5[16:0];  // .every("100ms") (line 12)
