  assign n26 = {{1{1'b0}}, counter_value} + {{8{1'b0}}, n22};  // $.value + 1 (line 18)
  assign n27 = (|counter_down) ? {{1{n23[8]}}, n23} : {{1{1'b0}}, n26};  // $.down ? $.value - 1 : $.value + 1 (line 18)
  assign n28 = n27[7:0];  // wrap($.down ? $.value - 1 : $.value + 1) (line 18)
  assign n30 = counter_value == {{7{1'b0}}, n29};  // $.value === 0 (line 20)
  assign n31 = (|counter_en) ? n28 : counter_value;  // $.value = wrap($.down ? $.value - 1 : $.value + 1) (line 18)
